class Solution {
  private int count = 0;

  private boolean isSafe(int[] cols, int row, int col) {
    for (int r = 0; r < row; r++) {
      if (cols[r] == col || Math.abs(cols[r] - col) == Math.abs(r - row)) {
        return false;
      }
    }
    return true;
  }

  private void backtrack(int n, int row, int[] cols) {
    if (row == n) {
      count++;
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(cols, row, col)) {
        cols[row] = col;
        backtrack(n, row + 1, cols);
      }
    }
  }

  public int totalNQueens(int n) {
    backtrack(n, 0, new int[n]);
    return count;
  }
}

class Solution:
    def totalNQueens(self, n: int) -> int:
        count = 0
        cols = [-1] * n

        def is_safe(row: int, col: int) -> bool:
            for r in range(row):
                if cols[r] == col or abs(cols[r] - col) == abs(r - row):
                    return False
            return True

        def backtrack(row: int):
            nonlocal count
            if row == n:
                count += 1
                return
            for col in range(n):
                if is_safe(row, col):
                    cols[row] = col
                    backtrack(row + 1)

        backtrack(0)
        return count

impl Solution {
  pub fn total_n_queens(n: i32) -> i32 {
    fn is_safe(cols: &[i32], row: i32, col: i32) -> bool {
      for r in 0..row {
        if cols[r as usize] == col || (cols[r as usize] - col).abs() == (r - row).abs() {
          return false;
        }
      }
      true
    }
    fn backtrack(n: i32, row: i32, cols: &mut Vec<i32>, count: &mut i32) {
      if row == n {
        *count += 1;
        return;
      }
      for col in 0..n {
        if is_safe(cols, row, col) {
          cols[row as usize] = col;
          backtrack(n, row + 1, cols, count);
        }
      }
    }
    let mut count = 0;
    let mut cols = vec![-1; n as usize];
    backtrack(n, 0, &mut cols, &mut count);
    count
  }
}

const totalNQueens = (n: number): number => {
  let count = 0;
  const cols: number[] = new Array(n).fill(-1);

  const isSafe = (row: number, col: number): boolean => {
    for (let r = 0; r < row; r++) {
      if (cols[r] === col || Math.abs(cols[r] - col) === Math.abs(r - row)) return false;
    }
    return true;
  };

  const backtrack = (row: number) => {
    if (row === n) {
      count++;
      return;
    }
    for (let col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        cols[row] = col;
        backtrack(row + 1);
      }
    }
  };

  backtrack(0);
  return count;
};
